mapper.select:
SELECT COUNT(*)
FROM financial_patterns
WHERE user_id = #{userId}
  AND shortcut_number = #{shortcutNumber}
  AND is_active = TRUE

SELECT COUNT(*) FROM bank_accounts
WHERE user_id = #{userId}
  AND bank_account_id = #{accountId}
  AND registered_person_id IS NOT NULL

mapper.insert:
INSERT INTO financial_patterns (
    user_id, shortcut_number, pattern_type, title, description, linked_bank_account_id
) VALUES (
    #{userId}, #{shortcutNumber}, #{patternType}, #{title}, #{description}, #{linkedAccountId}
)

INSERT INTO pattern_steps (
    financial_pattern_id, step_order, step_code, step_name,
    instruction_text, screen_code, target_element_id
) VALUES (
    #{patternId}, #{stepOrder}, #{stepCode}, #{stepName},
    #{instructionText}, #{screenCode}, #{targetElementId}
)

mapper.update:
UPDATE financial_patterns
SET voice_script_outdated = voice_script_outdated OR
        (voice_file_path IS NOT NULL AND BINARY description != BINARY #{description}),
    title = #{title},
    description = #{description},
    linked_bank_account_id = #{linkedAccountId}
WHERE user_id = #{userId}
  AND financial_pattern_id = #{patternId}
  AND is_active = TRUE

UPDATE pattern_steps ps
JOIN financial_patterns fp ON fp.financial_pattern_id = ps.financial_pattern_id
SET ps.voice_script_outdated = ps.voice_script_outdated OR
        (ps.voice_file_path IS NOT NULL AND BINARY ps.instruction_text != BINARY #{instructionText}),
    ps.instruction_text = #{instructionText}
WHERE fp.user_id = #{userId}
  AND fp.financial_pattern_id = #{patternId}
  AND fp.is_active = TRUE
  AND ps.step_code = #{stepCode}

UPDATE financial_patterns
SET is_active = FALSE, shortcut_number = NULL
WHERE user_id = #{userId}
  AND financial_pattern_id = #{patternId}
  AND is_active = TRUE

UPDATE financial_patterns
SET is_active = TRUE, shortcut_number = #{shortcutNumber}
WHERE user_id = #{userId} AND financial_pattern_id = #{patternId}

mapper.insert:
INSERT INTO pattern_executions (
    financial_pattern_id, source_bank_account_id, status, started_at
) VALUES (
    #{patternId}, #{sourceAccountId}, 'STARTED', #{startedAt}
)

mapper.select:
SELECT COUNT(*) FROM bank_accounts
WHERE user_id = #{userId}
  AND bank_account_id = #{accountId}
  AND registered_person_id IS NULL

SELECT COUNT(*)
FROM pattern_executions pe
JOIN financial_patterns fp ON fp.financial_pattern_id = pe.financial_pattern_id
JOIN pattern_steps ps ON ps.financial_pattern_id = fp.financial_pattern_id
WHERE fp.user_id = #{userId}
  AND pe.pattern_execution_id = #{executionId}
  AND pe.status = 'STARTED'
  AND ps.pattern_step_id = #{stepId}
  AND ps.step_code != 'TRANSFER_COMPLETE'

mapper.insert:
INSERT INTO step_execution_logs (
    pattern_execution_id, pattern_step_id, visit_number, started_at
) VALUES (
    #{executionId}, #{stepId}, #{visitNumber}, #{startedAt}
)

mapper.select:
SELECT sel.*
FROM step_execution_logs sel
JOIN pattern_executions pe ON pe.pattern_execution_id = sel.pattern_execution_id
JOIN financial_patterns fp ON fp.financial_pattern_id = pe.financial_pattern_id
WHERE fp.user_id = #{userId}
  AND sel.pattern_execution_id = #{executionId}
  AND sel.step_execution_log_id = #{visitId}
FOR UPDATE

SELECT sel.*
FROM step_execution_logs sel
JOIN pattern_executions pe ON pe.pattern_execution_id = sel.pattern_execution_id
JOIN financial_patterns fp ON fp.financial_pattern_id = pe.financial_pattern_id
WHERE fp.user_id = #{userId}
  AND sel.pattern_execution_id = #{executionId}
  AND sel.step_execution_log_id = #{visitId}

mapper.update:
UPDATE step_execution_logs
SET ended_at = #{endedAt}
WHERE pattern_execution_id = #{executionId} AND ended_at IS NULL

UPDATE pattern_executions pe
JOIN financial_patterns fp ON fp.financial_pattern_id = pe.financial_pattern_id
SET pe.status = #{status}, pe.ended_at = #{endedAt}
WHERE fp.user_id = #{userId}
  AND pe.pattern_execution_id = #{executionId}
  AND pe.status = 'STARTED'
